import hashlib

def compute_blake3_digest(filepath: str) -> str:
    """Compute cryptographic hash to short-circuit unchanged documents."""
    hasher = hashlib.sha256()
    with open(filepath, 'rb') as f:
        hasher.update(f.read())
    return hasher.hexdigest()

